(function() {
    'use strict';

    class BioTexAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'La Empresa que el Mundo Necesita';
            this.version = '1.1.0';

            this.INITIATIVES = {
                organic:   { cost: 800,  envDelta: 120, socDelta: 40,  govDelta: 0,   carbonDelta: -4100, lentiaDelta: 15, ebitdaDelta: -1.69, label: 'Organic Cotton' },
                waterless: { cost: 1900, envDelta: 150, socDelta: 20,  govDelta: 0,   carbonDelta: -2200, lentiaDelta: 18, ebitdaDelta: -0.55, label: 'Waterless Dyeing' },
                wage:      { cost: 310,  envDelta: 0,   socDelta: 110, govDelta: 0,   carbonDelta: 0,     lentiaDelta: 8,  ebitdaDelta: -0.66, label: 'Living Wage' },
                board:     { cost: 0,    envDelta: 0,   socDelta: 0,   govDelta: 100, carbonDelta: 0,     lentiaDelta: 4,  ebitdaDelta: 0,     label: 'Board Diversity' },
                ghg:       { cost: 80,   envDelta: 60,  socDelta: 0,   govDelta: 50,  carbonDelta: 0,     lentiaDelta: 8,  ebitdaDelta: -0.17, label: 'GHG Reporting' },
                iso:       { cost: 120,  envDelta: 70,  socDelta: 0,   govDelta: 0,   carbonDelta: 0,     lentiaDelta: 12, ebitdaDelta: -0.25, label: 'ISO 14001' }
            };

            this.ROUND_BRIEFINGS = [
                {
                    titleKey: 'r1_briefing_title',
                    textKey: 'r1_briefing_text'
                },
                {
                    titleKey: 'r2_briefing_title',
                    textKey: 'r2_briefing_text'
                },
                {
                    titleKey: 'r3_briefing_title',
                    textKey: 'r3_briefing_text'
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    esgScore: 200,
                    envScore: 250,
                    socScore: 280,
                    govScore: 300,
                    ebitdaMargin: 9.2,
                    carbonTotal: 14410,
                    scope1: 1240,
                    scope2: 890,
                    scope3Up: 8920,
                    scope3Down: 3360,
                    lentiaScore: 30,
                    greenwashIndex: 100,
                    stakeholderTrust: 40,
                    budgetRemaining: 3200,
                    investedInitiatives: [],
                    hasGHGReporting: false,
                    supplierIgnored: false,
                    carbonTaxActive: false,
                    esgHistory: [],
                    carbonHistory: [],
                    ebitdaHistory: [],
                    lentiaHistory: [],
                    eventLog: ''
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    round: 1,
                    initiatives: [],
                    supplierResponse: 'audit',
                    reportTone: 'transparent',
                    laborResponse: 'remediate',
                    ceoBonusLink: 'accept',
                    greenBond: 'yes',
                    scope3Disclosure: 'full'
                };
            }
            this._updateBriefing(state);
            this._updateBudgetDisplay(state);
        }

        validateDecisions(decisions) {
            var currentPeriod = window.mySimulation.state.currentPeriod || 1;
            decisions.round = currentPeriod;

            if (currentPeriod === 1) {
                var selected = [];
                var totalCost = 0;
                var ids = ['chkOrganic', 'chkWaterless', 'chkWage', 'chkBoard', 'chkGHG', 'chkISO'];
                var keys = ['organic', 'waterless', 'wage', 'board', 'ghg', 'iso'];

                for (var i = 0; i < ids.length; i++) {
                    var el = document.getElementById(ids[i]);
                    if (el && el.checked) {
                        selected.push(keys[i]);
                        totalCost += this.INITIATIVES[keys[i]].cost;
                    }
                }

                if (totalCost > 3200) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('budget_exceeded'), 'warning'
                    );
                    return false;
                }

                decisions.initiatives = selected;
                decisions.totalInvested = totalCost;

                var supplierEl = document.getElementById('supplierResponse');
                if (supplierEl) decisions.supplierResponse = supplierEl.value;
            }

            if (currentPeriod === 2) {
                var reportEl = document.getElementById('reportTone');
                if (reportEl) decisions.reportTone = reportEl.value;

                var laborEl = document.getElementById('laborResponse');
                if (laborEl) decisions.laborResponse = laborEl.value;

                var ceoEl = document.getElementById('ceoBonusLink');
                if (ceoEl) decisions.ceoBonusLink = ceoEl.value;
            }

            if (currentPeriod === 3) {
                var bondEl = document.getElementById('greenBond');
                if (bondEl) decisions.greenBond = bondEl.value;

                var scopeEl = document.getElementById('scope3Disclosure');
                if (scopeEl) decisions.scope3Disclosure = scopeEl.value;
            }

            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var envDelta = 0;
            var socDelta = 0;
            var govDelta = 0;
            var carbonDelta = 0;
            var lentiaDelta = 0;
            var ebitdaDelta = 0;
            var greenwashDelta = 0;
            var trustDelta = 0;
            var costsCOP = 0;
            var events = '';

            if (d.round === 1) {
                var initiatives = d.initiatives || [];
                for (var i = 0; i < initiatives.length; i++) {
                    var init = this.INITIATIVES[initiatives[i]];
                    if (init) {
                        envDelta += init.envDelta;
                        socDelta += init.socDelta;
                        govDelta += init.govDelta;
                        carbonDelta += init.carbonDelta;
                        lentiaDelta += init.lentiaDelta;
                        ebitdaDelta += init.ebitdaDelta;
                        costsCOP += init.cost;
                    }
                }

                ds.investedInitiatives = initiatives;
                ds.budgetRemaining = 3200 - costsCOP;
                ds.hasGHGReporting = initiatives.indexOf('ghg') !== -1;

                if (d.supplierResponse === 'audit') {
                    costsCOP += 50;
                    socDelta += 20;
                    trustDelta += 10;
                    ebitdaDelta -= 0.11;
                } else if (d.supplierResponse === 'terminate') {
                    socDelta += 40;
                    trustDelta += 15;
                    ebitdaDelta -= 0.30;
                } else {
                    ds.supplierIgnored = true;
                }

                events = window.mySimulation.t('event_carbon_tax');
                ds.carbonTaxActive = true;
            }

            if (d.round === 2) {
                var carbonTaxCost = ds.scope1 * 0.045;
                ebitdaDelta -= (carbonTaxCost / 473);

                if (d.reportTone === 'transparent') {
                    envDelta += 30;
                    socDelta += 20;
                    govDelta += 20;
                    trustDelta += 15;
                } else if (d.reportTone === 'aspirational') {
                    envDelta += 15;
                    socDelta += 10;
                    govDelta += 10;
                    greenwashDelta -= 20;
                    trustDelta += 3;
                } else {
                    envDelta += 5;
                    govDelta += 5;
                    trustDelta -= 5;
                }

                if (d.laborResponse === 'remediate') {
                    costsCOP += 200;
                    socDelta += 60;
                    trustDelta += 20;
                    ebitdaDelta -= 0.42;
                } else if (d.laborResponse === 'pr_statement') {
                    costsCOP += 20;
                    socDelta += 10;
                    greenwashDelta -= 15;
                    trustDelta -= 5;
                    ebitdaDelta -= 0.04;
                } else {
                    socDelta -= 20;
                    trustDelta -= 15;
                    ebitdaDelta -= 0.21;
                }

                if (d.ceoBonusLink === 'accept') {
                    govDelta += 80;
                } else if (d.ceoBonusLink === 'modify') {
                    govDelta += 40;
                }

                if (ds.supplierIgnored) {
                    var ngoRoll = Math.random();
                    if (ngoRoll < 0.4) {
                        events = window.mySimulation.t('event_ngo_documentary');
                        socDelta -= 30;
                        trustDelta -= 20;
                        greenwashDelta -= 15;
                    }
                }

                var csrdRoll = Math.random();
                if (csrdRoll < 0.35) {
                    events += (events ? '<br>' : '') + window.mySimulation.t('event_csrd_fasttrack');
                    lentiaDelta -= 5;
                }
            }

            if (d.round === 3) {
                if (d.greenBond === 'yes') {
                    if (ds.hasGHGReporting) {
                        govDelta += 60;
                        envDelta += 30;
                        ebitdaDelta += 0.30;
                        lentiaDelta += 5;
                    } else {
                        events = window.mySimulation.t('event_bond_rejected');
                        greenwashDelta -= 10;
                    }
                }

                if (d.scope3Disclosure === 'full') {
                    envDelta += 80;
                    socDelta += 20;
                    lentiaDelta += 15;
                    trustDelta += 10;
                } else if (d.scope3Disclosure === 'partial') {
                    envDelta += 40;
                    lentiaDelta += 8;
                    trustDelta += 3;
                } else {
                    lentiaDelta -= 5;
                }

                var acquisitionRoll = Math.random();
                var newEsg = this._calcESG(ds.envScore + envDelta, ds.socScore + socDelta, ds.govScore + govDelta);
                if (newEsg >= 600 && acquisitionRoll < 0.25) {
                    events += (events ? '<br>' : '') + window.mySimulation.t('event_acquisition_offer');
                }
            }

            ds.envScore = Math.min(1000, Math.max(0, ds.envScore + envDelta));
            ds.socScore = Math.min(1000, Math.max(0, ds.socScore + socDelta));
            ds.govScore = Math.min(1000, Math.max(0, ds.govScore + govDelta));
            ds.esgScore = Math.round(this._calcESG(ds.envScore, ds.socScore, ds.govScore));
            ds.ebitdaMargin = Math.round((ds.ebitdaMargin + ebitdaDelta) * 100) / 100;
            ds.carbonTotal = Math.max(0, ds.carbonTotal + carbonDelta);
            ds.lentiaScore = Math.min(100, Math.max(0, ds.lentiaScore + lentiaDelta));
            ds.greenwashIndex = Math.min(100, Math.max(0, ds.greenwashIndex + greenwashDelta));
            ds.stakeholderTrust = Math.min(100, Math.max(0, ds.stakeholderTrust + trustDelta));
            ds.eventLog = events;

            if (carbonDelta < 0) {
                var ratio = carbonDelta / 14410;
                var s1Reduction = Math.round(ds.scope1 * Math.abs(ratio));
                var s3Reduction = Math.abs(carbonDelta) - s1Reduction;
                ds.scope1 = Math.max(0, ds.scope1 - s1Reduction);
                ds.scope3Up = Math.max(0, ds.scope3Up - s3Reduction);
            }

            ds.esgHistory.push(ds.esgScore);
            ds.carbonHistory.push(ds.carbonTotal);
            ds.ebitdaHistory.push(ds.ebitdaMargin);
            ds.lentiaHistory.push(ds.lentiaScore);

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
                self._updateESGBars(ds);
                self._showEvent(ds.eventLog);
            }, 500);

            return {
                period: state.currentPeriod,
                round: d.round,
                esgScore: ds.esgScore,
                esgRating: this._getESGRating(ds.esgScore),
                envScore: ds.envScore,
                socScore: ds.socScore,
                govScore: ds.govScore,
                ebitdaMargin: ds.ebitdaMargin,
                carbonTotal: ds.carbonTotal,
                lentiaScore: ds.lentiaScore,
                greenwashIndex: ds.greenwashIndex,
                stakeholderTrust: ds.stakeholderTrust,
                events: events
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('esgDisplay', 'domainState.esgScore',
                function(v) { return Math.round(v) + '/1000'; });
            uiManager.bind('esgRating', 'domainState.esgScore',
                function(v) {
                    if (v >= 800) return 'AAA';
                    if (v >= 700) return 'AA';
                    if (v >= 600) return 'BB';
                    if (v >= 450) return 'B';
                    if (v >= 300) return 'CCC';
                    return 'CCC';
                });
            uiManager.bind('ebitdaDisplay', 'domainState.ebitdaMargin',
                function(v) { return v.toFixed(1) + '%'; });
            uiManager.bind('carbonDisplay', 'domainState.carbonTotal',
                function(v) { return Math.round(v).toLocaleString(); });
            uiManager.bind('lentiaDisplay', 'domainState.lentiaScore',
                function(v) { return Math.round(v) + '/100'; });
            uiManager.bind('greenwashDisplay', 'domainState.greenwashIndex',
                function(v) { return Math.round(v) + '/100'; });
            uiManager.bind('envDisplay', 'domainState.envScore',
                function(v) { return Math.round(v); });
            uiManager.bind('socDisplay', 'domainState.socScore',
                function(v) { return Math.round(v); });
            uiManager.bind('govDisplay', 'domainState.govScore',
                function(v) { return Math.round(v); });
        }

        getChartConfig() {
            return {
                esgChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [{
                            label: this._t('chart_esg_label'),
                            data: [],
                            borderColor: '#1b5e20',
                            backgroundColor: 'rgba(27,94,32,0.1)',
                            borderWidth: 3,
                            fill: true,
                            tension: 0.3
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: this._t('chart_esg_title') },
                            annotation: {
                                annotations: {
                                    targetLine: {
                                        type: 'line',
                                        yMin: 600,
                                        yMax: 600,
                                        borderColor: '#e65100',
                                        borderWidth: 2,
                                        borderDash: [6, 4],
                                        label: {
                                            display: true,
                                            content: this._t('chart_bb_target'),
                                            position: 'end'
                                        }
                                    }
                                }
                            }
                        },
                        scales: {
                            y: { beginAtZero: false, min: 0, max: 1000 }
                        }
                    }
                },
                carbonChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [{
                            label: this._t('chart_carbon_label'),
                            data: [],
                            backgroundColor: 'rgba(230,81,0,0.7)',
                            borderColor: '#e65100',
                            borderWidth: 2,
                            borderRadius: 6
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: this._t('chart_carbon_title') }
                        },
                        scales: {
                            y: { beginAtZero: true }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.esgHistory.map(function(_, i) { return 'Y' + (i + 1); });
            return {
                esgChart: {
                    labels: labels,
                    datasets: [{ data: state.domainState.esgHistory }]
                },
                carbonChart: {
                    labels: labels,
                    datasets: [{ data: state.domainState.carbonHistory }]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var lastResult = history[history.length - 1].results || {};
            var esg = lastResult.esgScore || 0;
            var ebitda = lastResult.ebitdaMargin || 0;
            var lentia = lastResult.lentiaScore || 0;
            var greenwash = lastResult.greenwashIndex || 0;
            var trust = lastResult.stakeholderTrust || 0;
            var carbon = lastResult.carbonTotal || 14410;

            var esgWeight = 0.35;
            var finWeight = 0.25;
            var lentiaWeight = 0.20;
            var gwWeight = 0.10;
            var trustWeight = 0.10;

            var esgPct = Math.min(100, (esg / 1000) * 100);
            var finPct = ebitda >= 8.5 ? 100 : (ebitda >= 7 ? 70 : (ebitda >= 5 ? 40 : 10));
            var lentiaPct = Math.min(100, lentia);
            var gwPct = greenwash;
            var trustPct = trust;

            var composite = Math.round(
                esgPct * esgWeight +
                finPct * finWeight +
                lentiaPct * lentiaWeight +
                gwPct * gwWeight +
                trustPct * trustWeight
            );

            var performanceKey = 'perf_needs';
            if (composite >= 75) performanceKey = 'perf_excellent';
            else if (composite >= 60) performanceKey = 'perf_good';
            else if (composite >= 45) performanceKey = 'perf_satisfactory';
            var performance = this._t(performanceKey);

            var insights = [];
            insights.push(this._t(esg >= 600 ? 'ins_esg_ok' : 'ins_esg_low'));
            insights.push(this._t(carbon <= 10087 ? 'ins_carbon_ok' : 'ins_carbon_miss'));
            insights.push(this._t(lentia >= 70 ? 'ins_lentia_ok' : 'ins_lentia_miss'));
            if (ebitda < 8.5) { insights.push(this._t('ins_ebitda_low')); }
            if (greenwash < 85) { insights.push(this._t('ins_greenwash_low')); }

            return {
                compositeScore: composite,
                esgRating: this._getESGRating(esg),
                esgScore: esg,
                ebitdaMargin: ebitda,
                carbonReduction: Math.round(((14410 - carbon) / 14410) * 100),
                lentiaScore: lentia,
                greenwashIndex: greenwash,
                performance: performance,
                performanceKey: performanceKey,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.round === 1) {
                if (results.ebitdaMargin < 7) return window.mySimulation.t('hint_financial_stress');
                if (results.carbonTotal > 13000) return window.mySimulation.t('hint_carbon_high');
            }
            if (results.round === 2) {
                if (results.greenwashIndex < 80) return window.mySimulation.t('hint_greenwash_risk');
                if (results.lentiaScore < 50) return window.mySimulation.t('hint_lentia_low');
            }
            if (results.round === 3) {
                if (results.esgScore < 500) return window.mySimulation.t('hint_esg_push');
            }
            return null;
        }

