            var panel = document.getElementById('eventPanel');
            if (!panel || !text) return;
            var titleEl = document.getElementById('eventTitle');
            var textEl = document.getElementById('eventText');
            if (titleEl) titleEl.textContent = '⚠ Event';
            if (textEl) textEl.innerHTML = text;
            panel.style.display = 'block';
